//===- fused_matmul_bias_gelu.cu - PolyKernel fused kernel ------*- CUDA -*-===//
//
// AUTO-GENERATED by `polykernel-opt --lower-to-cuda` (Todo 14 / Wave 3).
// Do not edit by hand; re-run the pass to regenerate.
//
// Fused MatMul + Bias + GELU (EPILOGUE fusion): out[M,N] = gelu(matmul(a,b)+bias).
// The per-column bias add + exact erf-based GELU are folded into the tiled GEMM's
// store: each block computes one BLOCK_M x BLOCK_N output tile, accumulating over K
// in BLOCK_K-wide tiles staged through shared memory (mirrors matmul.cu); after the
// accumulator is final, bias[col] is added and GELU applied BEFORE the bf16 store —
// so the matmul/bias intermediates are never materialized in global memory. Matches
// tests/golden/golden.py:
//     fused_matmul_bias_gelu(a, b, bias) = gelu(bias(matmul(a, b), bias)).
//
// ROUNDING CONTRACT (matches golden): bf16 inputs upcast exactly to fp32 for the
// multiply-accumulate; the matmul accumulator is rounded to bf16, the bias add is
// rounded to bf16, and the GELU output is rounded to bf16 (RNE) — replicating the
// per-stage bf16 rounding of the unfused primitive chain so the fused result is
// bit-identical to running matmul -> bias -> gelu in sequence. Bounds checks handle
// M/N/K that are not tile multiples. Written against the portable template
// (kernels/template/kernel_common.h) so it compiles UNCHANGED under
// `nvcc -DPOLYKERNEL_CUDA` and `hipcc -DPOLYKERNEL_HIP` (erff is device math on
// both; everything else is behind pk_* / PK_* macros).
//
//===----------------------------------------------------------------------===//

#include "../template/kernel_common.h"

namespace {

// Output tile per block + K-tile width (mirrors matmul.cu). One thread (tx, ty)
// computes one output element out[row, col]; blockDim == (kBlockN, kBlockM) ==
// 16 x 16 == 256 threads. gridDim.x tiles N (columns), gridDim.y tiles M (rows).
constexpr int kBlockM = 16;
constexpr int kBlockN = 16;
constexpr int kBlockK = 16;
constexpr float kInvSqrt2 = 0.70710678118654752440f; // 1 / sqrt(2)

// Exact erf-based GELU (mirrors gelu.cu): 0.5 * x * (1 + erf(x / sqrt(2))).
PK_DEVICE_INLINE float gelu_one(float x) {
  return 0.5f * x * (1.0f + erff(x * kInvSqrt2));
}

PK_GLOBAL void fused_matmul_bias_gelu_kernel(const pk_bf16 *__restrict__ A,
                                             const pk_bf16 *__restrict__ B,
                                             const pk_bf16 *__restrict__ bias,
                                             pk_bf16 *__restrict__ C, int M,
                                             int N, int K) {
  PK_SHARED pk_bf16 As[kBlockM][kBlockK];
  PK_SHARED pk_bf16 Bs[kBlockK][kBlockN];

  const int tx = threadIdx.x; // column within the output tile [0, kBlockN)
  const int ty = threadIdx.y; // row within the output tile    [0, kBlockM)
  const int row = blockIdx.y * kBlockM + ty;
  const int col = blockIdx.x * kBlockN + tx;

  // fp32 accumulator (matches golden: np.matmul on fp32(bf16(a)), fp32(bf16(b))).
  float acc = 0.0f;

  const int numKTiles = (K + kBlockK - 1) / kBlockK;
  for (int t = 0; t < numKTiles; ++t) {
    // Stage A[row, t*kBlockK + tx] and B[t*kBlockK + ty, col] into shared mem.
    // Out-of-bounds loads (non-tile-multiple M/N/K) read as 0 so they never
    // contribute to the accumulator.
    int aCol = t * kBlockK + tx;
    As[ty][tx] = (row < M && aCol < K) ? A[static_cast<size_t>(row) * K + aCol]
                                       : pk_float2bf16(0.0f);
    int bRow = t * kBlockK + ty;
    Bs[ty][tx] = (bRow < K && col < N) ? B[static_cast<size_t>(bRow) * N + col]
                                       : pk_float2bf16(0.0f);
    pk_syncthreads();

    // Accumulate this K-tile in fp32 (bf16 upcast exactly on each read).
#pragma unroll
    for (int kk = 0; kk < kBlockK; ++kk)
      acc += pk_bf162float(As[ty][kk]) * pk_bf162float(Bs[kk][tx]);
    pk_syncthreads();
  }

  // Epilogue fusion (bias THEN gelu, before store). Each stage rounds to bf16 to
  // replicate the unfused primitive chain bit-for-bit (golden composes matmul ->
  // bias -> gelu, each bf16-rounded): matmul acc -> bf16 -> +bias[col] -> bf16 ->
  // gelu -> bf16 store. bias[col] is the per-output-column bias (last axis).
  if (row < M && col < N) {
    float mm = pk_bf162float(pk_float2bf16(acc)); // matmul output rounded to bf16
    float biased =
        pk_bf162float(pk_float2bf16(mm + pk_bf162float(bias[col]))); // bias -> bf16
    C[static_cast<size_t>(row) * N + col] = pk_float2bf16(gelu_one(biased));
  }
}

} // namespace

// Host-callable launch entry (the launch_*-style ABI). out[M,N] =
// gelu(matmul(a, b) + bias); a is [M,K] (batched leading dims flattened into M by
// the caller), b is [K,N], bias is [N] (broadcast over the output columns). The
// stream is passed as void* to keep the signature backend-agnostic and cast to the
// backend stream type (pk_stream_t) inside.
void launch_fused_matmul_bias_gelu(const pk_bf16 *a, const pk_bf16 *b,
                                   const pk_bf16 *bias, pk_bf16 *output, int M,
                                   int N, int K, void *stream) {
  dim3 block(kBlockN, kBlockM);
  dim3 grid((N + kBlockN - 1) / kBlockN, (M + kBlockM - 1) / kBlockM);
  pk_stream_t s = static_cast<pk_stream_t>(stream);
  PK_LAUNCH(fused_matmul_bias_gelu_kernel, grid, block, 0, s, a, b, bias, output,
            M, N, K);
  PK_CHECK(pk_get_last_error());
}
